建設工事は、代金を先に払っても現物がすぐ手に入りません。しかも出来上がったものが手抜きでも、素人の発注者には見分けがつきません。だから国は「一定規模以上の工事を請け負う会社は、事前に役所の審査を受けて営業の免許を取っておきなさい」というルールを置きました。これが建設業の許可です。逆にごく小さい工事まで全部許可制にすると町の大工さんが仕事できなくなるので、金額の小さいものは「軽微な建設工事」として許可なしで請け負えます。試験ではこの境目の金額が繰り返し問われます。

