　その内装仕上を自社施工｜内装の許可は不要｜内装工事の専門技術者★｜
　内装仕上のみを800万円で受注｜内装仕上工事業★｜内装仕上の主任技術者★｜
　附帯する電気工事を自社施工｜電気の許可は不要｜電気工事の専門技術者★｜
　⚠一式の許可は万能パスではない。専門工事を単独受注するには専門の許可が要る

