許可を取った会社には、取っただけでは終わらない日常の義務があります。ひとつは「見せる義務」。営業所と工事現場に標識（金看板）を掲げ、誰の責任で工事をしているかを外から分かるようにします。もうひとつは「残す義務」。営業所ごとに帳簿を備え、契約や下請の記録を保存します。何か問題が起きたときに、誰がいつ何を約束したのかを追えるようにするためです。試験では標識の記載事項と、帳簿・書類の保存年数が数字で問われます。

━━━━━━━━━━━━━━━━━━━━━━
