        id: 'sk-ho-n10', title: '請負契約の原則と契約書面の記載事項', emoji: '📝',
        body: `▼ゼロから：口約束は必ずもめる。だから書面が義務
建設工事はやってみないと分からない部分が多く、追加工事や工期の延長が日常茶飯事です。ここで契約書がなければ「言った・言わない」の水掛け論になり、立場の弱い下請が泣きを見ます。そこで建設業法は、請負契約を結ぶときは着工前に必ず書面を交わし、しかも書くべき項目を法律で列挙しました。これが第19条です。列挙された項目は現在16号まであり、令和2年改正で工期変更や災害時の取扱いなどが追加されました。試験では「書面に記載しなくてよいもの」を選ばせる形式が定番です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 請負契約の基本原則
━━━━━━━━━━━━━━━━━━━━━━
・建設工事の請負契約の当事者は、各々の対等な立場における合意に基づいて公正な契約を締結し、信義に従って誠実に履行しなければならない（第18条）★
・請負契約の当事者は、契約の締結に際して所定の事項を書面に記載し、署名または記名押印をして相互に交付しなければならない（第19条第1項）★
・書面の交付は工事の着手前に行う★
・当事者双方の承諾を得れば、電子情報処理組織を使用する方法（電子契約）によることができる★
・契約内容を変更するときも、変更の内容を書面に記載して相互に交付する（第19条第2項）★
・請負契約の書面は、元請と下請の間でも同じく必要である★

━━━━━━━━━━━━━━━━━━━━━━
🔑 契約書面の記載事項（第19条第1項の主なもの）
━━━━━━━━━━━━━━━━━━━━━━
・工事内容★
・請負代金の額★
・工事着手の時期および工事完成の時期★
・工事を施工しない日または時間帯の定めをするときは、その内容★（令和2年追加）
・請負代金の全部または一部の前金払または出来形部分に対する支払の定めをするときは、その支払の時期および方法★
・当事者の一方から設計変更または工事着手の延期もしくは工事の全部・一部の中止の申出があった場合における工期の変更、請負代金の額の変更または損害の負担およびそれらの額の算定方法★
・天災その他不可抗力による工期の変更または損害の負担およびその額の算定方法★
・価格等の変動・変更に基づく請負代金の額または工事内容の変更★
・工事の施工により第三者が損害を受けた場合における賠償金の負担に関する定め★
・注文者が工事に使用する資材を提供し、または建設機械その他の機械を貸与するときは、その内容および方法に関する定め★
・注文者が工事の全部または一部の完成を確認するための検査の時期および方法ならびに引渡しの時期★
・工事完成後における請負代金の支払の時期および方法★
・工事の目的物が種類または品質に関して契約の内容に適合しない場合における担保責任またはその責任の履行に関して講ずべき保証保険契約の締結その他の措置に関する定めをするときは、その内容★
・各当事者の履行の遅滞その他債務の不履行の場合における遅延利息、違約金その他の損害金★
・契約に関する紛争の解決方法★
・その他国土交通省令で定める事項

【図解】契約書面の記載事項で狙われる論点
　項目｜記載義務｜ひっかけの形｜
　工事内容・請負代金・工期｜必須★｜省略できるとするのは誤り｜
　工事を施工しない日・時間帯｜定めるときは必須★｜令和2年改正で追加｜
　主任技術者・監理技術者の氏名｜記載事項ではない★｜記載必須とするのは誤り｜
　現場代理人の権限｜第19条の2の通知事項★｜契約書の必要的記載事項ではない｜
　⚠技術者の氏名は契約書ではなく標識・施工体制台帳の記載事項

━━━━━━━━━━━━━━━━━━━━━━
🔑 現場代理人の選任等に関する通知（第19条の2）
━━━━━━━━━━━━━━━━━━━━━━
・請負人は、現場代理人を置く場合、その権限に関する事項および注文者の請負人に対する意見の申出方法を、書面により注文者に通知する★
・注文者は、監督員を置く場合、同様に請負人に書面で通知する★
・現場代理人は、工事現場における請負人の代理人であって、建設業法上の資格要件はない★
・現場代理人と主任技術者・監理技術者は兼ねることができる★
・現場代理人は工事現場に常駐することを求められるのが一般的だが、公共工事標準請負契約約款では発注者の承諾を得て常駐を要しない扱いが認められる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「請負契約書は工事完成後に取り交わせばよい」→ ×。着手前に交付する
・「契約の変更は口頭でよい」→ ×。変更時も書面が必要★
・「主任技術者の氏名は契約書面の必要的記載事項である」→ ×
・「電子契約は認められない」→ ×。双方の承諾があれば可
・「工事を施工しない日の定めは記載事項ではない」→ ×。令和2年改正で追加された★
・「下請契約では書面の交付は不要」→ ×。元請下請を問わず必要

★ここだけ暗記
　契約は対等・公正・信義誠実。着手前に書面を相互交付し、変更時も書面。記載事項は工事内容・代金・工期を筆頭に16項目。技術者の氏名は記載事項ではない。現場代理人は権限を書面で通知し、主任技術者との兼務は可。`,
