現場事務所や資材倉庫、災害時の応急仮設住宅、博覧会のパビリオン。これらは工事期間や催事期間が終われば取り壊される一時的な建築物です。ここに恒久的な建物と同じ基準（防火地域の耐火要求、建蔽率、接道義務、内装制限など）をすべてかけるのは合理的ではありません。そこで建築基準法第85条は、非常災害の応急仮設建築物と工事用仮設建築物について、多くの規定の適用を除外しています。ただし、除外されない規定もあり、そこが問われます。

