　接道義務・建蔽率・容積率★｜適用されない★｜敷地内に自由に配置できる｜
　防火地域・準防火地域の制限★｜適用されない★｜耐火建築物とする必要がない｜
　構造耐力（第20条）・避雷設備（第33条）★｜適用される★｜安全に直結するため除外されない★｜
　⚠構造耐力と避雷設備は適用される。ここが最頻出のひっかけ

