        body: `▼ゼロから：救急車と消防車が入れない土地に建物は建てられない
建築基準法にとって「道路」は、単なる通行の場ではなく、火災時の消防活動と避難のためのライフラインです。だから、敷地は必ず道路に接していなければならず（接道義務）、道路には最低限の幅が求められます。そして、幅が足りない古い道については、将来の拡幅を見越して敷地側を後退させる（セットバック）ルールが用意されています。これらは第42条（道路の定義）と第43条（接道義務）に集約されています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築基準法上の道路（第42条第1項）
━━━━━━━━━━━━━━━━━━━━━━
・原則として幅員4m以上のもので、次のいずれかに該当するもの★
　・第1号：道路法による道路（国道、都道府県道、市町村道）★
　・第2号：都市計画法、土地区画整理法、都市再開発法等による道路★
　・第3号：法の規定が適用されるに至った際、現に存在する道（既存道路）★
　・第4号：都市計画法等により2年以内に事業が執行される予定のもので特定行政庁が指定したもの★
　・第5号：土地を建築物の敷地として利用するため築造する道で、特定行政庁からその位置の指定を受けたもの（位置指定道路）★
・特定行政庁が指定する区域内では、幅員6m以上が原則となる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 2項道路（みなし道路）とセットバック
━━━━━━━━━━━━━━━━━━━━━━
・法の規定が適用されるに至った際、現に建築物が立ち並んでいる幅員4m未満の道で、特定行政庁の指定したものは、道路とみなす（第42条第2項）★
・この場合、道路の中心線から水平距離2mの線が道路の境界線とみなされる★
・敷地の反対側が崖地、川、線路敷地等である場合は、その境界線から4mの線が道路の境界線となる★
・後退した部分（セットバック部分）は敷地面積に算入できない★
・セットバック部分には、建築物はもちろん、門や塀も築造できない★
・幅員6m区域の指定がある場合は、中心線から3mの後退が必要となる

【図解】道路と接道義務の数値
　項目｜数値★｜備考｜
　建築基準法上の道路の幅員｜原則4m以上★｜特定行政庁指定区域は6m以上★｜
　2項道路のセットバック｜中心線から2m★｜片側が崖・川なら反対側から4m★｜
　接道義務｜幅員4m以上の道路に2m以上接する★｜第43条第1項★｜
　路地状敷地（旗竿地）の路地幅｜条例により3m以上等｜地方公共団体の条例で強化可★｜
　⚠「4m以上の道路に2m以上接する」の2つの数字はセットで覚える

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地等と道路との関係＝接道義務（第43条）
━━━━━━━━━━━━━━━━━━━━━━
・建築物の敷地は、道路（自動車のみの交通の用に供する道路等を除く）に2m以上接しなければならない★
・自動車専用道路（高速道路）や地区計画の区域内の道路等には接道の効果がない★
・次の場合は接道義務の適用が除外される★
　・その敷地が幅員4m以上の道に2m以上接し、利用者が少数であるものとして国土交通省令で定める基準に適合する建築物で、特定行政庁が認めたもの★
　・その周囲に広い空地を有する建築物その他国土交通省令で定める基準に適合する建築物で、特定行政庁が建築審査会の同意を得て許可したもの（但し書き許可）★
・地方公共団体は、条例で、特殊建築物、階数3以上の建築物、延べ面積1,000m²を超える建築物等について、接道の長さを付加することができる（第43条第3項）★
・接道義務を緩和する条例を定めることはできない（強化のみ可能）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 道路内の建築制限（第44条）と私道の変更・廃止（第45条）
━━━━━━━━━━━━━━━━━━━━━━
・建築物または敷地を造成するための擁壁は、道路内に、または道路に突き出して建築・築造してはならない★
・例外として、次のものは道路内に建築できる★
　・地盤面下に設ける建築物（地下街、地下駐車場等）★
　・公衆便所、巡査派出所その他これらに類する公益上必要な建築物で、特定行政庁が通行上支障がないと認めて建築審査会の同意を得て許可したもの★
　・公共用歩廊（アーケード）その他政令で定める建築物で、特定行政庁が許可したもの★
・私道の変更または廃止によって、その道路に接する敷地が接道義務に抵触することとなる場合、特定行政庁はその私道の変更または廃止を禁止し、または制限することができる★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「敷地は道路に1.8m以上接すればよい」→ ×。2m以上★
・「セットバック部分も敷地面積に算入できる」→ ×。算入できない★
・「2項道路は道路の中心線から3m後退する」→ ×。原則2m★
・「地方公共団体は条例で接道義務を緩和できる」→ ×。強化のみ★
・「地盤面下に設ける建築物も道路内には建築できない」→ ×。建築できる★
・「幅員4m未満の道はすべて建築基準法上の道路でない」→ ×。特定行政庁が指定した2項道路は道路とみなされる★
・「高速道路に2m以上接していれば接道義務を満たす」→ ×。自動車専用道路は除かれる★

★ここだけ暗記
　道路は原則幅員4m以上（指定区域は6m）。2項道路は中心線から2m後退、後退部分は敷地面積不算入。接道は幅員4m以上の道路に2m以上。条例による強化は可、緩和は不可。道路内建築は原則禁止だが地盤面下は可。`,
