        id: 'sk-ho-n30', title: '建蔽率の計算と緩和規定', emoji: '📏',
        body: `▼ゼロから：敷地の何割まで建物で覆ってよいかの上限
敷地いっぱいに建物を建てると、隣家との間に隙間がなくなり、火災が燃え広がり、日当たりも風通しも失われます。そこで用途地域ごとに「敷地面積のうち建築面積が占めてよい割合」の上限が定められています。これが建蔽率です。ただし、角地であったり、防火地域内の耐火建築物であったりすれば、防火や環境の面で有利なので割増しが認められます。計算問題として出題されることが多く、緩和の組合せを正しく足せるかが勝負です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 建蔽率の基本（第53条）
━━━━━━━━━━━━━━━━━━━━━━
・建蔽率＝建築面積÷敷地面積★
・建築面積＝建築物の外壁またはこれに代わる柱の中心線で囲まれた部分の水平投影面積★
・ひさし、軒、バルコニー等で、外壁または柱の中心線から水平距離1m以上突き出たものは、その先端から1m後退した線までを建築面積に算入する★
・地階で地盤面上1m以下にある部分は建築面積に算入しない★
・用途地域ごとの建蔽率の限度（都市計画で定める）
　・第一種・第二種低層住居専用地域、田園住居地域：30・40・50・60%のうち定めるもの★
　・近隣商業地域：60・80%★
　・商業地域：80%（固定）★
　・工業地域：50・60%、工業専用地域：30・40・50・60%★
・用途地域の指定のない区域：30・40・50・60・70%のうち特定行政庁が定めるもの★

━━━━━━━━━━━━━━━━━━━━━━
🔑 建蔽率の緩和（第53条第3項・第6項）
━━━━━━━━━━━━━━━━━━━━━━
・特定行政庁が指定する角地：10%（1/10）加算★
・防火地域内にある耐火建築物等（都市計画の建蔽率が80%以外の地域）：10%加算★
・準防火地域内にある耐火建築物等または準耐火建築物等：10%加算★
・角地かつ防火地域内の耐火建築物等：20%加算（合計）★
・防火地域内で、都市計画の建蔽率が80%とされている地域内の耐火建築物等：建蔽率の制限が適用されない（100%）★
・巡査派出所、公衆便所、公共用歩廊等は建蔽率の制限を受けない★
・公園、広場、道路、川等の内にある建築物で特定行政庁が安全上・防火上・衛生上支障がないと認めて許可したものも適用除外★

【図解】建蔽率の緩和の組合せ
　条件｜加算★｜結果の例（基準60%）｜
　特定行政庁指定の角地｜＋10%★｜70%★｜
　防火地域内の耐火建築物等｜＋10%★｜70%★｜
　角地＋防火地域内の耐火建築物等｜＋20%★｜80%★｜
　防火地域内で都市計画80%の地域の耐火建築物等｜制限なし★｜100%★｜
　⚠準防火地域では準耐火建築物等でも＋10%が受けられる

━━━━━━━━━━━━━━━━━━━━━━
🔑 建築面積に算入しない部分の整理
━━━━━━━━━━━━━━━━━━━━━━
・軒、ひさし、はね出しバルコニー、外気に有効に開放されている廊下等で、外壁または柱の中心線から水平距離1m以上突き出た部分は、その先端から1m後退した線までを算入する★
　→ 出が1m以下なら建築面積に算入しない★
・地階で地盤面上1m以下にある部分は算入しない★
・国土交通大臣が高い開放性を有すると認めて指定する構造（カーポート等で外壁のない部分が連続して4m以上、天井の高さ2.1m以上、地階を除く階数1等）の建築物は、端から水平距離1mを後退した線までを算入する★
・敷地面積には、2項道路のセットバック部分、都市計画道路の予定地部分（一部）は算入しない★
・建築面積は「水平投影面積」であり、床面積とは異なる概念である★
・延べ面積は各階の床面積の合計。容積率の計算に用いる（建蔽率には用いない）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地が2以上の地域にわたる場合
━━━━━━━━━━━━━━━━━━━━━━
・敷地が建蔽率の異なる2以上の地域にわたる場合、それぞれの地域に属する敷地部分の面積の割合に応じて加重平均する★
・計算例：敷地300m²のうち200m²が建蔽率60%の地域、100m²が建蔽率80%の地域の場合
　・許容建築面積＝200×0.6＋100×0.8＝120＋80＝200m²★
　・敷地全体の建蔽率＝200÷300＝約66.7%★
・敷地が防火地域と準防火地域にわたる場合、その敷地内の建築物の全部が耐火建築物等であるときは、敷地全部が防火地域内にあるものとみなして緩和を適用する★
・敷地が防火地域の内外にわたる場合も同様の考え方をとる

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「建蔽率は延べ面積を敷地面積で除して求める」→ ×。それは容積率。建蔽率は建築面積★
・「角地の緩和はすべての角地に適用される」→ ×。特定行政庁が指定する角地★
・「準防火地域内の準耐火建築物には緩和の適用がない」→ ×。10%加算される★
・「商業地域の建蔽率は都市計画で60%または80%から選ぶ」→ ×。商業地域は80%固定★
・「軒の出が1.5mの場合、軒の全部を建築面積に算入する」→ ×。先端から1m後退した線まで★
・「建蔽率の異なる地域にわたる場合、厳しいほうの数値を敷地全体に適用する」→ ×。加重平均★

★ここだけ暗記
　建蔽率＝建築面積÷敷地面積。角地指定＋10%、防火地域内の耐火建築物等＋10%、両方で＋20%。都市計画80%の防火地域内の耐火建築物等は制限なし（100%）。軒の出は1m超の部分から1m後退線まで算入。2地域にわたるときは加重平均。`,
