        body: `▼ゼロから：床の総量を抑えて、街のインフラ容量に合わせる
建蔽率が「敷地の何割を覆うか」の規制だとすれば、容積率は「敷地の何倍の床をつくれるか」の規制です。床が増えれば人が増え、車が増え、下水も電気も必要になります。街のインフラが受け止められる量に建物のボリュームを合わせるための道具が容積率です。しかも、前面道路が狭ければ、都市計画で定められた数値よりさらに厳しい制限がかかります。この「道路幅員による低減」の計算が試験の定番です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 容積率の基本（第52条）
━━━━━━━━━━━━━━━━━━━━━━
・容積率＝延べ面積÷敷地面積★
・延べ面積＝各階の床面積の合計★
・都市計画で定める指定容積率
　・第一種・第二種低層住居専用地域、田園住居地域：50・60・80・100・150・200%★
　・住居系地域（中高層・住居地域）：100〜500%★
　・近隣商業・準工業地域：100〜500%
　・商業地域：200〜1300%★
　・工業・工業専用地域：100〜400%★
・実際に適用される容積率は、指定容積率と前面道路幅員による容積率のいずれか小さいほう★

━━━━━━━━━━━━━━━━━━━━━━
🔑 前面道路の幅員による容積率の制限
━━━━━━━━━━━━━━━━━━━━━━
・前面道路の幅員が12m未満である場合、その幅員のメートル数に一定の数値（低減係数）を乗じた値が容積率の上限となる★
　・住居系の用途地域：4/10★
　・その他の用途地域（商業・工業・近隣商業・準工業等）および用途地域無指定区域：6/10★
・前面道路が2以上ある場合は、最大の幅員を用いる★
・幅員12m以上の道路に接する場合は、この制限を受けず指定容積率がそのまま適用される★
・計算例：第一種住居地域、指定容積率300%、前面道路幅員6mの場合
　・道路による容積率＝6×4/10＝2.4＝240%★
　・指定容積率300%と比較して小さいほうを採用 → 240%★
・計算例：商業地域、指定容積率600%、前面道路幅員8mの場合
　・道路による容積率＝8×6/10＝4.8＝480%★ → 480%を採用

【図解】容積率の計算に使う数値
　項目｜数値★｜備考｜
　住居系用途地域の低減係数｜4/10★｜前面道路幅員12m未満のとき適用★｜
　その他の用途地域の低減係数｜6/10★｜商業・工業・近隣商業・準工業等★｜
　制限を受けない道路幅員｜12m以上★｜指定容積率がそのまま適用｜
　前面道路が複数｜最大の幅員を採用★｜最小ではない★｜
　⚠実際の容積率は「指定容積率」と「道路による容積率」の小さいほう

━━━━━━━━━━━━━━━━━━━━━━
🔑 延べ面積に算入しない部分（容積率の緩和）
━━━━━━━━━━━━━━━━━━━━━━
・自動車車庫等の部分：建築物全体の延べ面積の1/5を限度として不算入★
・住宅・老人ホーム等の地階（天井が地盤面から1m以下）：住宅等の用途に供する部分の床面積の1/3を限度として不算入★
・エレベーターの昇降路の部分：全部不算入★
・共同住宅・老人ホーム等の共用の廊下・階段の部分：全部不算入★
・宅配ボックスを設ける部分：延べ面積の1/100を限度として不算入★
・備蓄倉庫：1/50、蓄電池設置部分：1/50、自家発電設備：1/100、貯水槽：1/100★
・特定行政庁の許可による総合設計制度、特定道路による緩和なども別に存在する

━━━━━━━━━━━━━━━━━━━━━━
🔑 敷地が2以上の地域にわたる場合と特定道路の緩和
━━━━━━━━━━━━━━━━━━━━━━
・敷地が容積率の異なる2以上の地域にわたる場合は、面積按分による加重平均で求める★
・計算例：敷地400m²のうち200m²が容積率200%、200m²が容積率300%の場合
　・許容延べ面積＝200×2.0＋200×3.0＝400＋600＝1,000m²★
　・全体の容積率＝1,000÷400＝250%★
・特定道路（幅員15m以上の道路）から70m以内にある敷地で、前面道路の幅員が6m以上12m未満の場合、前面道路の幅員に一定の数値Waを加算できる★
　・Wa＝(12−Wr)×(70−L)÷70（Wr：前面道路幅員、L：特定道路までの距離）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「容積率は建築面積を敷地面積で除して求める」→ ×。延べ面積★
・「前面道路が2以上ある場合、最小の幅員を用いる」→ ×。最大の幅員★
・「住居系地域の低減係数は6/10である」→ ×。4/10★
・「前面道路の幅員が10mなら道路による制限を受けない」→ ×。12m未満なので受ける★
・「地下車庫は全部が延べ面積に算入されない」→ ×。延べ面積の1/5が限度★
・「共同住宅の共用廊下は延べ面積の1/3まで不算入」→ ×。全部不算入★
・「エレベーターの昇降路は延べ面積に算入する」→ ×。不算入★

★ここだけ暗記
　容積率＝延べ面積÷敷地面積。前面道路12m未満なら幅員×4/10（住居系）または×6/10（その他）と指定容積率の小さいほう。道路が複数なら最大幅員。車庫は1/5、住宅地階は1/3、EV昇降路と共用廊下は全部不算入。`,
