        id: 'sk-ho-n50', title: '廃棄物処理法とマニフェスト制度', emoji: '🗑️',
        body: `▼ゼロから：出した者が最後まで責任を持つ
建設工事は大量の廃棄物を出します。かつては不法投棄が横行し、処理を委託した業者が山に捨てても、出した会社は「知らなかった」で済んでいました。そこで廃棄物処理法は「排出事業者責任」を徹底し、最終処分が終わるまで排出事業者が責任を負う仕組みにしました。その追跡の道具がマニフェスト（産業廃棄物管理票）です。誰が排出事業者になるのか、マニフェストの返送期限は何日か。この2点が試験の核心です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 産業廃棄物と排出事業者
━━━━━━━━━━━━━━━━━━━━━━
・産業廃棄物＝事業活動に伴って生じた廃棄物のうち、燃え殻、汚泥、廃油、廃酸、廃アルカリ、廃プラスチック類その他政令で定める20種類★
・建設工事に伴う産業廃棄物の例：がれき類（コンクリート塊、アスファルト塊）、木くず、金属くず、ガラスくず・コンクリートくずおよび陶磁器くず、汚泥、廃プラスチック類、紙くず、繊維くず★
・建設工事に伴い生ずる廃棄物については、元請業者が排出事業者となる★
　→ 下請業者が排出事業者となるのではない（平成23年改正で明確化）★
・特別管理産業廃棄物＝爆発性、毒性、感染性その他の人の健康または生活環境に係る被害を生ずるおそれがある性状を有するもの★
　・廃石綿等（飛散性アスベスト）、廃PCB等、廃油（引火点70度未満）、強酸・強アルカリ★
・特別管理産業廃棄物を生ずる事業場には、特別管理産業廃棄物管理責任者を置かなければならない★

━━━━━━━━━━━━━━━━━━━━━━
🔑 排出事業者の責務と保管基準
━━━━━━━━━━━━━━━━━━━━━━
・事業者は、その事業活動に伴って生じた廃棄物を自らの責任において適正に処理しなければならない★
・産業廃棄物の運搬または処分を他人に委託する場合は、許可を受けた収集運搬業者・処分業者に委託しなければならない★
・委託契約は書面により行い、契約書は契約終了の日から5年間保存しなければならない★
・収集運搬と処分は、それぞれ別個に直接契約する（二者間契約）★
・保管基準：周囲に囲いを設け、見やすい箇所に掲示板（縦横60cm以上）を設置する★
・屋外で容器を用いずに保管する場合、積上げ高さの制限がある（囲いに接しない場合は勾配50%以下等）★
・建設工事に伴う産業廃棄物の現場内保管は、原則として排出場所での保管に限られる★

【図解】マニフェスト（産業廃棄物管理票）の運用
　票の種類｜返送する者｜期限★｜
　B2票（運搬終了）｜収集運搬業者★｜運搬終了から10日以内★｜
　D票（処分終了）｜処分業者★｜処分終了から10日以内★｜
　E票（最終処分終了）｜処分業者★｜最終処分終了から10日以内★｜
　排出事業者の保存｜A票・B2票・D票・E票★｜5年間保存★｜
　⚠B2・D票は交付から90日以内（特別管理産業廃棄物は60日）、E票は180日以内に返送がなければ都道府県知事へ報告

━━━━━━━━━━━━━━━━━━━━━━
🔑 マニフェスト制度の詳細
━━━━━━━━━━━━━━━━━━━━━━
・排出事業者は、産業廃棄物の運搬または処分を委託する場合、産業廃棄物の引渡しと同時にマニフェストを交付しなければならない★
・マニフェストは、産業廃棄物の種類ごと、運搬先ごとに交付する★
・排出事業者は、送付されたマニフェスト（B2・D・E票）を5年間保存しなければならない★
・返送期限内にマニフェストの送付を受けないとき、または記載事項に虚偽の記載があるときは、生活環境の保全上の措置を講ずるとともに、30日以内に都道府県知事に報告しなければならない★
・電子マニフェストの利用が推進されており、前々年度の特別管理産業廃棄物（PCB廃棄物を除く）の発生量が年間50t以上の事業場は電子マニフェストの使用が義務化されている★
・多量排出事業者（前年度の産業廃棄物発生量1,000t以上等）は、処理計画を作成して都道府県知事に提出する★
・毎年度、産業廃棄物管理票交付等状況報告書を都道府県知事に提出する（6月30日まで）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 処理業者の許可と委託基準
━━━━━━━━━━━━━━━━━━━━━━
・産業廃棄物収集運搬業・処分業は、都道府県知事（政令市長）の許可を受けなければならない★
・許可の有効期間は5年（優良認定業者は7年）★
・積替え保管を行う場合は、その旨の許可が必要★
・収集運搬業の許可は、積込みを行う都道府県と荷下ろしを行う都道府県の両方で必要★
・自ら運搬する場合（排出事業者が自社運搬する場合）は許可不要だが、運搬車に必要事項を表示し、書面を備え付けなければならない★
・不法投棄をした者には、5年以下の懲役もしくは1,000万円以下の罰金（法人は3億円以下の罰金）★
・委託基準違反、マニフェスト未交付にも罰則がある★

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・過去問での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「建設工事の廃棄物の排出事業者は下請業者である」→ ×。元請業者★
・「マニフェストの保存期間は3年である」→ ×。5年★
・「B2票の返送期限は運搬終了から30日以内」→ ×。10日以内★
・「収集運搬業者と処分業者に一括して委託契約を結べる」→ ×。それぞれと直接契約★
・「産業廃棄物処理業の許可の有効期間は3年である」→ ×。5年★
・「委託契約書の保存期間は3年である」→ ×。5年★
・「排出事業者が自ら運搬する場合も収集運搬業の許可が必要」→ ×。不要★

★ここだけ暗記
　建設工事の排出事業者は元請。マニフェストはB2・D票が10日以内返送、排出事業者は5年保存。未返送は交付から90日（特管60日）、E票180日で知事へ報告。委託契約書も5年保存、収運と処分は別々に直接契約。処理業の許可は知事、有効期間5年。`,
