　・場所を移動しないで、道路に露店、屋台店その他これらに類する店を出そうとする者★
　・道路において祭礼行事をし、またはロケーションをする等、一般交通に著しい影響を及ぼすような通行の形態もしくは方法により道路を使用する行為等★
・許可権者は所轄警察署長★
