・道路管理者と警察署長は相互に協議を行う★

【図解】道路に関する許可の使い分け
　行為｜必要な許可★｜許可権者★｜
　足場・仮囲い・朝顔を道路上に設ける｜道路占用許可＋道路使用許可★｜道路管理者＋警察署長★｜
　道路上での掘削工事・舗装工事｜道路占用許可＋道路使用許可★｜道路管理者＋警察署長★｜
　資材搬入車両の一時停車・積卸し｜道路使用許可★｜警察署長★｜
　道路の構造に影響を与える工事｜道路管理者の承認（第24条）★｜道路管理者★｜
　⚠占用は「継続して道路を使用」、使用は「工事・作業等の行為」。両方要る場面が多い

━━━━━━━━━━━━━━━━━━━━━━
