・公共工事の品質確保の促進に関する法律（公共工事品確法）：総合評価落札方式の活用、ダンピング対策、発注関係事務の適切な実施を発注者の責務とする★
・低入札価格調査制度・最低制限価格制度により、著しく低い価格での落札を防止する★
・令和元年改正で、災害時の緊急対応、働き方改革の推進、生産性向上、調査・設計の品質確保が追加された★

